M(gshop, r"""
public static boolean armed(java.util.UUID u, String k, int R) {
  Object o = u == null ? null : ARM.get(u);
  if (!(o instanceof String)) return false;
  String s = (String) o;
  int a = s.lastIndexOf('|');
  if (a < 0) return false;
  long at = 0L;
  try { at = Long.parseLong(s.substring(a + 1)); } catch (Throwable t) { return false; }
  long now = System.currentTimeMillis();
  return s.substring(0, a).equals(k + "|" + R) && now >= at && now - at <= 10000L;
}""")
